// ============================================================
// Node 4: Parse & Filter Jobs
// ============================================================
// Receives raw markdown from both GitHub repos (SimplifyJobs + SpeedyApply)
// Parses markdown tables, extracts structured job entries,
// applies keyword + location filters, and skips closed/citizenship entries.
// ============================================================

const simplifyRaw = $('Fetch SimplifyJobs').first().json.data || '';
const speedyRaw = $('Fetch SpeedyApply').first().json.data || '';

// --- Configuration ---
const ROLE_KEYWORDS = [
  'swe', 'software', 'full stack', 'fullstack', 'full-stack',
  'backend', 'back-end', 'back end',
  'frontend', 'front-end', 'front end',
  'ai', 'ml', 'machine learning', 'artificial intelligence',
  'python', 'genai', 'generative ai',
  'data engineer', 'platform engineer', 'devops', 'cloud',
  'systems engineer', 'infrastructure', 'site reliability',
  'developer', 'engineering intern', 'web developer'
];

const LOCATION_KEYWORDS = [
  'boston', 'cambridge', 'somerville', 'waltham',
  'remote', 'ma', 'massachusetts', 'united states',
  'new york', 'ny', 'san francisco', 'sf',
  'hybrid', 'usa', 'anywhere'
];

// Emoji flags to skip
const SKIP_CLOSED = '🔒';
const SKIP_CITIZENSHIP = ['🛂', '🇺🇸'];

// --- Helper Functions ---

function extractMarkdownLink(text) {
  const match = text.match(/\[([^\]]*)\]\(([^)]*)\)/);
  if (match) {
    return { text: match[1].trim(), url: match[2].trim() };
  }
  return { text: text.trim(), url: '' };
}

function extractAllLinks(cell) {
  const links = [];
  const regex = /\[([^\]]*)\]\(([^)]*)\)/g;
  let match;
  while ((match = regex.exec(cell)) !== null) {
    links.push({ text: match[1].trim(), url: match[2].trim() });
  }
  return links;
}

function cleanText(text) {
  return text
    .replace(/<[^>]+>/g, '')
    .replace(/\*\*/g, '')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function shouldSkipEntry(rowText) {
  if (rowText.includes(SKIP_CLOSED)) return true;
  for (const flag of SKIP_CITIZENSHIP) {
    if (rowText.includes(flag)) return true;
  }
  return false;
}

function matchesRoleKeywords(role) {
  const roleLower = role.toLowerCase();
  return ROLE_KEYWORDS.some(keyword => roleLower.includes(keyword));
}

function matchesLocationKeywords(location) {
  const locLower = location.toLowerCase();
  return LOCATION_KEYWORDS.some(keyword => locLower.includes(keyword));
}

// --- Parsing Functions ---

function parseSimplifyJobs(markdown) {
  const jobs = [];
  const lines = markdown.split('\n');
  let inTable = false;
  let headerParsed = false;

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed.startsWith('|')) {
      if (inTable && headerParsed) {
        inTable = false;
        headerParsed = false;
      }
      continue;
    }

    if (trimmed.match(/^\|[\s\-:|]+\|$/)) {
      inTable = true;
      continue;
    }

    if (!headerParsed && inTable) {
      const lowerTrimmed = trimmed.toLowerCase();
      if (lowerTrimmed.includes('company') || lowerTrimmed.includes('role') || lowerTrimmed.includes('name')) {
        headerParsed = true;
        continue;
      }
    }

    if (!inTable) {
      const lowerTrimmed = trimmed.toLowerCase();
      if (lowerTrimmed.includes('company') && (lowerTrimmed.includes('role') || lowerTrimmed.includes('location'))) {
        inTable = true;
        headerParsed = true;
        continue;
      }
      continue;
    }

    if (shouldSkipEntry(trimmed)) continue;

    const cells = trimmed.split('|').filter(c => c.trim() !== '');
    if (cells.length < 3) continue;

    const companyInfo = extractMarkdownLink(cells[0]);
    const role = cleanText(cells[1]);
    const location = cleanText(cells[2]);

    let applyUrl = '';
    if (cells.length >= 4) {
      const links = extractAllLinks(cells[3]);
      if (links.length > 0) {
        applyUrl = links[0].url;
      }
    }

    let datePosted = '';
    if (cells.length >= 5) {
      datePosted = cleanText(cells[cells.length - 1]);
    }

    const company = companyInfo.text || cleanText(cells[0]);
    const companyUrl = companyInfo.url;

    if (company && role) {
      jobs.push({
        company,
        companyUrl,
        role,
        location,
        applyUrl: applyUrl || companyUrl,
        datePosted,
        source: 'SimplifyJobs'
      });
    }
  }

  return jobs;
}

function parseSpeedyApply(markdown) {
  const jobs = [];
  const lines = markdown.split('\n');
  let inTable = false;
  let headerParsed = false;

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed.startsWith('|')) {
      if (inTable && headerParsed) {
        inTable = false;
        headerParsed = false;
      }
      continue;
    }

    if (trimmed.match(/^\|[\s\-:|]+\|$/)) {
      inTable = true;
      continue;
    }

    if (!headerParsed && inTable) {
      const lowerTrimmed = trimmed.toLowerCase();
      if (lowerTrimmed.includes('company') || lowerTrimmed.includes('name')) {
        headerParsed = true;
        continue;
      }
    }

    if (!inTable) {
      const lowerTrimmed = trimmed.toLowerCase();
      if (lowerTrimmed.includes('company') && (lowerTrimmed.includes('role') || lowerTrimmed.includes('location') || lowerTrimmed.includes('title'))) {
        inTable = true;
        headerParsed = true;
        continue;
      }
      continue;
    }

    if (shouldSkipEntry(trimmed)) continue;

    const cells = trimmed.split('|').filter(c => c.trim() !== '');
    if (cells.length < 3) continue;

    const companyInfo = extractMarkdownLink(cells[0]);
    const role = cleanText(cells[1]);
    const location = cleanText(cells[2]);

    let applyUrl = '';
    if (cells.length >= 4) {
      const links = extractAllLinks(cells[3]);
      if (links.length > 0) {
        applyUrl = links[0].url;
      } else {
        const urlMatch = cells[3].trim().match(/https?:\/\/[^\s]+/);
        if (urlMatch) applyUrl = urlMatch[0];
      }
    }

    let datePosted = '';
    if (cells.length >= 5) {
      datePosted = cleanText(cells[cells.length - 1]);
    }

    const company = companyInfo.text || cleanText(cells[0]);
    const companyUrl = companyInfo.url;

    if (company && role) {
      jobs.push({
        company,
        companyUrl,
        role,
        location,
        applyUrl: applyUrl || companyUrl,
        datePosted,
        source: 'SpeedyApply'
      });
    }
  }

  return jobs;
}

// --- Main Execution ---
const simplifyJobs = parseSimplifyJobs(simplifyRaw);
const speedyJobs = parseSpeedyApply(speedyRaw);
const allJobs = [...simplifyJobs, ...speedyJobs];

const filteredJobs = allJobs.filter(job => {
  const roleMatch = matchesRoleKeywords(job.role);
  const locationMatch = matchesLocationKeywords(job.location);
  return roleMatch && locationMatch;
});

const seen = new Set();
const uniqueJobs = filteredJobs.filter(job => {
  const key = `${job.company.toLowerCase().trim()}:${job.role.toLowerCase().trim()}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return uniqueJobs.map(job => ({ json: job }));

// ============================================================
// Node 7: Dedup & Filter
// ============================================================
// Receives parsed+filtered jobs from Node 4 and existing DB records
// from Node 5 (PostgreSQL). Cross-references both sources to output
// only genuinely new job entries.
// ============================================================

const parsedJobs = $('Parse & Filter Jobs').all();
const existingDbJobs = $('Fetch Existing Jobs').all();
const staticData = $getWorkflowStaticData('global');

if (!staticData.seenJobs) {
  staticData.seenJobs = {};
}

const dbJobSet = new Set();
for (const item of existingDbJobs) {
  const company = (item.json.company || '').toLowerCase().trim();
  const role = (item.json.role || '').toLowerCase().trim();
  if (company && role) {
    dbJobSet.add(`${company}:${role}`);
  }
}

const newJobs = [];

for (const item of parsedJobs) {
  const job = item.json;
  const company = (job.company || '').toLowerCase().trim();
  const role = (job.role || '').toLowerCase().trim();
  const key = `${company}:${role}`;

  if (dbJobSet.has(key)) continue;
  if (staticData.seenJobs[key]) continue;

  staticData.seenJobs[key] = new Date().toISOString();
  newJobs.push({ json: job });
}

if (newJobs.length === 0) {
  return [{ json: { _noNewJobs: true, message: 'No new jobs found after deduplication.' } }];
}

return newJobs;

// ============================================================
// Node 11: Parse Score
// ============================================================
// Parses the Gemini quick-score JSON response.
// Handles both clean JSON and markdown-wrapped JSON responses.
// ============================================================

const item = $input.first().json;

let responseText = item.text || item.output || item.response || '';

if (typeof responseText === 'object') {
  return [{
    json: {
      ...item,
      score: responseText.score || 0,
      visa_eligible: responseText.visa_eligible !== false,
      location_match: responseText.location_match !== false,
      reasoning: responseText.reasoning || 'No reasoning provided',
      _parsed: true
    }
  }];
}

let jsonStr = responseText;
const codeBlockMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)```/);
if (codeBlockMatch) {
  jsonStr = codeBlockMatch[1].trim();
}

try {
  const parsed = JSON.parse(jsonStr);
  return [{
    json: {
      ...item,
      score: parsed.score || 0,
      visa_eligible: parsed.visa_eligible !== false,
      location_match: parsed.location_match !== false,
      reasoning: parsed.reasoning || 'No reasoning provided',
      _parsed: true
    }
  }];
} catch (e) {
  const scoreMatch = responseText.match(/"score"\s*:\s*(\d+)/);
  const visaMatch = responseText.match(/"visa_eligible"\s*:\s*(true|false)/);
  const locationMatch = responseText.match(/"location_match"\s*:\s*(true|false)/);
  const reasonMatch = responseText.match(/"reasoning"\s*:\s*"([^"]+)"/);

  return [{
    json: {
      ...item,
      score: scoreMatch ? parseInt(scoreMatch[1]) : 0,
      visa_eligible: visaMatch ? visaMatch[1] === 'true' : true,
      location_match: locationMatch ? locationMatch[1] === 'true' : true,
      reasoning: reasonMatch ? reasonMatch[1] : 'Could not parse Gemini response',
      _parsed: false,
      _parseError: e.message
    }
  }];
}

